    if (['sync-bundle-candidates', 'add-case', 'remove-case', 'add-criterion', 'remove-criterion', 'apply-protocol-json', 'sync-protocol-json', 'download-protocol'].includes(action)) { captureBundle(); const d = state.bundleDraft; if (action === 'sync-bundle-candidates') { if (!state.selected.size) throw new Error('Select at least one candidate.'); d.candidateIds = [...state.selected]; } if (action === 'add-case') { if (d.cases.length >= 30) throw new Error('Maximum 30 cases.'); let id = d.cases.length + 1; while (d.cases.some(c => c.id === 'case-' + id)) id++; d.cases.push({ id: 'case-' + id, input: '', expected: '' }); } if (action === 'remove-case') d.cases.splice(Number(b.dataset.index), 1); if (action === 'add-criterion') { if (d.rubric.length >= 10) throw new Error('Maximum 10 rubric criteria.'); let id = d.rubric.length + 1; while (d.rubric.some(r => r.id === 'criterion-' + id)) id++; d.rubric.push({ id: 'criterion-' + id, label: '', weight: 1, maxScore: 4, anchors: '' }); } if (action === 'remove-criterion') d.rubric.splice(Number(b.dataset.index), 1); if (action === 'apply-protocol-json') { const cases = JSON.parse($('#bundle-cases').value), rubric = JSON.parse($('#bundle-rubric').value); if (!Array.isArray(cases) || !cases.length || cases.length > 30 || cases.some(c => !c || typeof c.id !== 'string' || typeof c.input !== 'string' || typeof c.expected !== 'string')) throw new Error('Cases must be an array of 1–30 objects with id, input and expected text.'); if (!Array.isArray(rubric) || !rubric.length || rubric.length > 10 || rubric.some(r => !r || typeof r.id !== 'string' || typeof r.label !== 'string' || typeof r.anchors !== 'string' || typeof r.weight !== 'number' || typeof r.maxScore !== 'number')) throw new Error('Rubric requires 1–10 criteria with id, label, weight, maxScore and anchors.'); d.cases = cases; d.rubric = rubric; } if (action === 'download-protocol') { downloadJSON('skillforge-cases-rubric.json', { cases: d.cases, rubric: d.rubric, caseSet: d.caseSet, reusedFrom: d.reusedFrom || null }); return; } render(); }
    if (action === 'import-pack') { try { if (!state.packFiles.length) throw new Error('Choose a directory or pack files first.'); const files = [], paths = new Set(); let total = 0; for (const item of state.packFiles) { const path = item.path; if (!path || path.length > 240 || /[\\\\\u0000-\u001f\u007f:]/.test(path) || path.startsWith('/') || path.split('/').some(p => !p || p === '.' || p === '..')) throw new Error('Unsafe relative pack path: ' + path); if (paths.has(path.toLowerCase())) throw new Error('Duplicate pack path: ' + path); paths.add(path.toLowerCase()); if (item.file.size > 1024 * 1024) throw new Error('Each file must be at most 1 MiB.'); total += item.file.size; const bytes = new Uint8Array(await item.file.arrayBuffer()); let text = ''; for (let i = 0; i < bytes.length; i += 8192) text += String.fromCharCode(...bytes.subarray(i, i + 8192)); files.push({ path, base64: btoa(text) }); } if (files.length > 100 || total > 2 * 1024 * 1024) throw new Error('Pack limit: 100 files including SKILL.md and 2 MiB total decoded bytes.'); if (!files.some(f => f.path === 'SKILL.md')) throw new Error('The pack needs exact root path SKILL.md. Edit the selected file paths.'); const response = await api('/api/import', { format: 'folder', files, title: $('#import-title').value.trim() || undefined }); state.packFiles = []; await refresh(); render(); feedback('pack-feedback', `Imported ${response.count} complete pack(s). All resources remain inert; review trust warnings before use.`); } catch (err) { feedback('pack-feedback', err.message, true); } }
