    if (action === 'submit-run') { captureRun(); try { const run = currentRun(), payload = { ...state.evaluation.results, runs: [run] }; await api('/api/results', payload); await refresh(); render(); feedback('run-feedback', 'Run validated and submitted. Remaining incomplete work stays in the separate draft.'); } catch (err) { feedback('run-feedback', err.message, true); } }
