    if (action === 'export-report') downloadJSON('skillforge-decision-report.json', state.report);
    if (action === 'edit-revision') { const s = state.skills.find(s => s.id === b.dataset.id); state.revisionSource = s.id; $('#dialog-content').innerHTML = `<div class="dialog-top"><h2 id="dialog-title">Edit exact SKILL.md revision</h2><button class="close-dialog" data-action="close-dialog" aria-label="Close revision editor">×</button></div>${notice('Creates a new immutable candidate. Companion resources, original attribution and upstream warnings are retained. Existing frozen bundles and their evidence are never changed.', 'purple')}<form id="revision-form" class="form-stack"><label class="field">Revision title<input name="title" maxlength="120" required value="${E((s.title + ' revision').slice(0, 120))}"></label><label class="field">Exact SKILL.md text<textarea id="revision-content" name="content" maxlength="120000" minlength="20" rows="20" spellcheck="false" required>${E(s.content)}</textarea></label><details><summary class="field-label">Preserved resource manifest</summary><pre class="code-block">${E(JSON.stringify(s.manifest, null, 2))}</pre></details><p class="small-description">Source complete pack SHA-256: ${E(s.hash)}<br>The editor preserves all companion resource bytes. Browser text areas normalize line endings to LF; the saved SKILL.md uses the exact edited text shown here.</p><div class="inline-actions"><button type="submit" class="button primary">Save immutable revision</button>${button('Cancel', 'cancel-revision', 'secondary')}</div><div id="revision-feedback" role="status"></div></form>`; }
    if (action === 'cancel-revision') showSkill(state.revisionSource);
    if (action === 'restore-preview') { try { if (!state.backup) throw new Error('Choose a workspace backup first.'); const result = await api('/api/restore-preview', { backup: state.backup }); state.restorePreview = result.preview; render(); } catch (err) { state.restorePreview = null; feedback('restore-feedback', err.message, true); } }
