    if (action === 'suggestion') { state.query = b.dataset.query; await search(); render(); }
    if (action === 'filter') { state.category = b.dataset.category; render(); }
    if (action === 'select') { captureBundle(); select(b.dataset.id); }
    if (action === 'dialog-select') { select(b.dataset.id); $('#skill-dialog').close(); toast('Comparison shortlist updated.'); }
