      const section = names => { const lines = s.content.split('\n'); let active = false; const found = []; for (const line of lines) { if (/^##\s/.test(line)) { if (active) break; active = names.some(n => line.toLowerCase().includes(n)); } else if (active) found.push(line); } return found.join('\n').trim(); };
      const steps = section(['workflow', 'steps', 'process']).split('\n').map(s => s.replace(/^\d+[.)]\s*/, '').trim()).filter(s => s.length >= 10).slice(0, 10);
