    if (action === 'import-results') await busy(b, async () => { try { const content = await readFile(state.resultFile); let input; try { input = JSON.parse(content); } catch { throw new Error('Invalid JSON. Check the results template and try again.'); } const result = await api('/api/results', input); await refresh(); render(); feedback('results-feedback', `Imported ${result.result.runs.length} ${result.result.kind} run(s). Scores were recomputed from the supplied judgments. ${result.result.kind === 'demo' ? 'Synthetic data is shown separately.' : 'Execution claims are user-supplied, not independently verified.'}`); state.resultFile = null; } catch (e) { feedback('results-feedback', e.message, true); } });
