document.addEventListener('change', event => { if (event.target.id === 'skill-file') { state.importFile = event.target.files[0]; $('#skill-file-info').textContent = state.importFile ? `${state.importFile.name} · ${Math.ceil(state.importFile.size / 1024)} KB` : ''; } if (event.target.id === 'results-file') { state.resultFile = event.target.files[0]; $('#results-file-info').textContent = state.resultFile ? `${state.resultFile.name} · ${Math.ceil(state.resultFile.size / 1024)} KB` : ''; } });
document.addEventListener('input', event => {
  if (event.target.closest('#compose-form')) captureCompose();
  if (event.target.closest('#bundle-form') && !['bundle-cases', 'bundle-rubric'].includes(event.target.id)) captureBundle();
  if (event.target.closest('#profile-form')) state.profileForm = profilePayload();
  if (event.target.closest('#run-form')) captureRun();
  if (event.target.closest('#decision-form')) state.decisionRequirements = readRequirements($('#decision-form'));
  if (event.target.id === 'shortlist-name') state.shortlistName = event.target.value;
  if (event.target.id === 'compose-draft-name') state.composeName = event.target.value;
  if (event.target.id === 'evaluation-draft-name' && state.evaluation) state.evaluation.name = event.target.value;
  if (event.target.dataset.packPath !== undefined) state.packFiles[Number(event.target.dataset.packPath)].path = event.target.value;
});
document.addEventListener('change', async event => { const el = event.target; try {
  if (['discovery-profile', 'decision-profile'].includes(el.id)) { captureRun(); await activateProfile(el.value); }
  if (el.id === 'profile-id') { state.profileForm = clone(state.profiles.find(p => p.id === el.value) || null); delete state.conflicts.profile; render(); }
  if (el.id === 'shortlist-select' && el.value) { const s = state.shortlists.find(s => s.id === el.value); state.shortlistSaved = clone(s); state.shortlistName = s.name; state.selected = new Set(s.candidateIds); delete state.conflicts.shortlist; render(); }
  if (['compose-draft-select', 'evaluation-draft-select'].includes(el.id) && el.value) { const draft = state.drafts.find(d => d.id === el.value); if (!window.confirm('Load this saved draft and replace the current unsaved editor contents?')) { el.value = ''; return; } loadDraft(draft); render(); }
  if (el.id === 'reuse-bundle') { captureBundle(); if (el.value) { const b = state.bundles.find(b => b.id === el.value); state.bundleDraft.cases = clone(b.cases); state.bundleDraft.caseSet = 'development'; } render(); }
  if (el.id === 'evaluation-run') { captureRun(); state.evaluation.index = Number(el.value); render(); }
  if (el.id === 'evaluation-kind') { captureRun(); if (!window.confirm('Changing result kind starts an empty notebook so synthetic content cannot silently become observed evidence. Save the current draft first if needed.')) { el.value = state.evaluation.results.kind; return; } const e = state.evaluation, bundle = state.bundles.find(b => b.id === e.bundleId); e.results = templateFor(bundle); e.results.kind = el.value; e.saved = null; e.index = 0; render(); }
  if (el.id === 'output-case') { captureRun(); state.inspection.caseId = el.value; render(); }
  if (el.id === 'output-repetition') { captureRun(); state.inspection.repetition = Number(el.value); render(); }
  if (el.id === 'decision-bundle') state.decisionBundleId = el.value;
  if (['pack-directory', 'pack-files'].includes(el.id)) { const files = [...el.files]; if (files.length > 100) throw new Error('Select at most100 files including SKILL.md.'); state.packFiles = files.map(file => { const relative = file.webkitRelativePath || file.name; return { file, path: file.webkitRelativePath ? relative.split('/').slice(1).join('/') : relative }; }); $('#pack-file-list').innerHTML = packFileList(); }
  if (el.id === 'backup-file') { state.restorePreview = null; state.backup = null; const file = el.files[0]; if (!file) return; if (file.size > 52 * 1024 * 1024 - 4096) throw new Error('Backup exceeds the52 MiB restore request budget.'); state.backup = JSON.parse(await file.text()); state.backupName = file.name + ' · ' + (file.size / 1024 / 1024).toFixed(2) + ' MiB'; render(); }
  if (el.id === 'restore-confirm') $('[data-action="restore-confirm"]').disabled = !el.checked;
} catch (err) { toast(err.message, true); } });
document.addEventListener('submit', async event => {
  event.preventDefault(); const form = event.target; const submit = form.querySelector('[type="submit"]');
  if (form.id === 'search-form') { await busy(submit, async () => { try { state.query = new FormData(form).get('query'); await search(); render(); } catch(e) { toast(e.message, true); } }); }
  if (form.id === 'compose-form') await busy(submit, async () => { try { captureCompose(); const input = composeData(); if (!input.workflow?.length) delete input.workflow; const result = await api('/api/compose', input); await refresh(); state.draft = {}; state.composeSaved = null; state.composeName = ''; render(); showSkill(result.skill.id); toast('Your skill is saved locally. Review the workflow, then download the ZIP.'); } catch(e) { feedback('compose-feedback', e.message, true); } });
  if (form.id === 'bundle-form') await busy(submit, async () => { try { captureBundle(); const d = state.bundleDraft; const input = { title: d.title, candidateIds: d.candidateIds, model: { id: d.modelId, capabilities: state.model.capabilities }, conditions: { systemPrompt: d.systemPrompt, temperature: Number(d.temperature), maxOutputTokens: Number(d.maxOutputTokens), repetitions: Number(d.repetitions), seed: d.seed === '' ? null : Number(d.seed), tools: d.tools, environment: d.environment, judge: d.judge }, cases: d.cases, rubric: d.rubric, caseSet: d.caseSet, ...(d.reusedFrom ? { reusedFrom: d.reusedFrom } : {}) }; await api('/api/bundles', input); state.bundleDraft = null; await refresh(); location.hash = 'evidence'; toast('Evaluation frozen with the remembered candidate IDs. Record actual runs in the notebook or download the external JSON template.'); } catch(e) { feedback('bundle-feedback', e.message, true); } });
  if (form.id === 'profile-form') await busy(submit, async () => { await saveItem('profile', 'profiles', profilePayload(), 'profile-feedback'); });
  if (form.id === 'revision-form') await busy(submit, async () => { try { const fd = new FormData(form); const result = await api('/api/revisions', { sourceId: state.revisionSource, title: fd.get('title'), content: fd.get('content') }); await refresh(); $('#skill-dialog').close(); render(); showSkill(result.skill.id); toast('New immutable revision saved. Resources and attribution preserved; previous evidence is unchanged.'); } catch (err) { feedback('revision-feedback', err.message, true); } });
  if (form.id === 'decision-form') await busy(submit, async () => { try { state.decisionBundleId = $('#decision-bundle').value; state.decisionRequirements = readRequirements(form); const result = await api('/api/decision', { bundleId: state.decisionBundleId, requirements: state.decisionRequirements, ...(state.activeProfileId ? { profileId: state.activeProfileId } : {}) }); state.report = result.report; captureRun(); render(); $('.decision-report').scrollIntoView(); } catch (err) { feedback('decision-feedback', err.message, true); } });
});
$('#skill-dialog').addEventListener('click', event => { if (event.target === $('#skill-dialog')) $('#skill-dialog').close(); });
window.addEventListener('hashchange', route);
refresh().then(route).catch(error => { main.innerHTML = `<div class="empty-state"><h1>Could not open the workbench.</h1><p>${E(error.message)}</p><p>Check the local server console, then reload this page.</p><button class="button primary" id="reload">Reload</button></div>`; $('#reload').addEventListener('click', () => location.reload()); });
